class Funcionario {
  #salario;

  constructor(nome, salario) {
    this.nome = nome;
    this.#salario = salario;
  }

  get salarioAnual() {
    return this.#salario * 14;
  }

  static criar(dados) {
    return new Funcionario(dados.nome, dados.salario);
  }
}

class Gestor extends Funcionario {
  constructor(nome, salario, equipa) {
    super(nome, salario);
    this.equipa = equipa;
  }

  get salarioAnual() {
    return super.salarioAnual + 2000;
  }
}

const gestor = new Gestor('Rita', 2000, ['Ana', 'Bruno']);
console.log(gestor.salarioAnual); // 30000

// Com .then / .catch
function obterUtilizadorComThen(id) {
  return fetch(`/api/utilizadores/${id}`)
    .then((resposta) => resposta.json())
    .then((dados) => dados.nome)
    .catch((erro) => {
      console.error('Falhou:', erro);
      throw erro;
    });
}

// A mesma lógica com async/await
async function obterUtilizadorComAwait(id) {
  try {
    const resposta = await fetch(`/api/utilizadores/${id}`);
    const dados = await resposta.json();
    return dados.nome;
  } catch (erro) {
    console.error('Falhou:', erro);
    throw erro;
  }
}

class ErroValidacao extends Error {
  constructor(mensagem) {
    super(mensagem);
    this.name = 'ErroValidacao';
  }
}

function validarIdade(idade) {
  if (idade < 0) {
    throw new ErroValidacao('idade não pode ser negativa');
  }
  return idade;
}

try {
  validarIdade(-5);
} catch (erro) {
  console.error(`${erro.name}: ${erro.message}`);
} finally {
  console.log('validação terminada');
}

