exercises.statement:
Tem um array de encomendas. Cada encomenda tem preco e cliente, mas cliente pode ser null ou não ter a propriedade desconto. Use reduce, optional chaining e nullish coalescing para calcular o total a pagar (preco menos o desconto, sendo o desconto 0 quando não existir ou o cliente for null).

const encomendas = [
  { preco: 100, cliente: { desconto: 10 } },
  { preco: 50, cliente: {} },
  { preco: 80, cliente: null },
];

exercises.solution_code:
const encomendas = [
  { preco: 100, cliente: { desconto: 10 } },
  { preco: 50, cliente: {} },
  { preco: 80, cliente: null },
];

const total = encomendas.reduce((acumulado, encomenda) => {
  const desconto = encomenda.cliente?.desconto ?? 0;
  return acumulado + (encomenda.preco - desconto);
}, 0);

console.log(total); // 220

class SaldoInsuficienteError extends Error {
  constructor(valorPedido, saldoDisponivel) {
    super(`Saldo insuficiente: pedido ${valorPedido}€, disponível ${saldoDisponivel}€`);
    this.name = 'SaldoInsuficienteError';
  }
}

class ContaBancaria {
  #saldo;

  constructor(saldoInicial) {
    this.#saldo = saldoInicial;
  }

  get saldo() {
    return this.#saldo;
  }

  async levantar(valor) {
    await new Promise((resolve) => setTimeout(resolve, 100));

    if (valor > this.#saldo) {
      throw new SaldoInsuficienteError(valor, this.#saldo);
    }

    this.#saldo -= valor;
    return this.#saldo;
  }
}

async function testarLevantamentos() {
  const contaA = new ContaBancaria(100);
  const contaB = new ContaBancaria(30);

  const resultados = await Promise.allSettled([
    contaA.levantar(50),
    contaB.levantar(50),
  ]);

  resultados.forEach((resultado, indice) => {
    if (resultado.status === 'fulfilled') {
      console.log(`Conta ${indice}: novo saldo ${resultado.value}€`);
    } else {
      console.error(`Conta ${indice}: ${resultado.reason.message}`);
    }
  });
}

testarLevantamentos();
// Conta 0: novo saldo 50€
// Conta 1: SaldoInsuficienteError: Saldo insuficiente: pedido 50€, disponível 30€
